export const FIXED_FACTION_VASSALS=Object.freeze(FIXED_HIERARCHY_ROWS.map(r=>Object.freeze({overlordId:r[0],vassalId:r[1],type:'VASSAL',tribute:r[6],autonomy:r[7],protection:r[8],sinceCycle:0,territoryId:r[2],overlordJurisdictionId:r[3],vassalJurisdictionId:r[4],fixed:true})));
const hierarchyRelations=FIXED_HIERARCHY_ROWS.map(r=>Object.freeze({id:relationId(r[0],r[1]),a:r[0],b:r[1],type:'VASSAL',trust:r[9],fear:0,respect:r[10],grievance:0,economicDependency:r[11],militaryDependency:r[12],tags:Object.freeze(['fixed','geographic_hierarchy',r[5]])}));
export const FIXED_SUPREME_RELATIONS=Object.freeze(FIXED_SUPREME_RELATION_ROWS.map(r=>Object.freeze({id:relationId(r[0],r[1]),a:r[0],b:r[1],type:r[2],trust:r[3],fear:r[4],respect:r[5],grievance:r[6],economicDependency:r[7],militaryDependency:r[8],tags:Object.freeze(['fixed','supreme'])})));
export const FIXED_GEOGRAPHIC_RELATIONS=Object.freeze(hierarchyRelations);export const FIXED_FACTION_RELATIONS=Object.freeze([...FIXED_SUPREME_RELATIONS,...FIXED_GEOGRAPHIC_RELATIONS]);
const VASSALS_BY_TERRITORY=new Map();for(const l of FIXED_FACTION_VASSALS){if(!l.territoryId)continue;if(!VASSALS_BY_TERRITORY.has(l.territoryId))VASSALS_BY_TERRITORY.set(l.territoryId,[]);VASSALS_BY_TERRITORY.get(l.territoryId).push(l);}
export function getFixedVassalsForTerritory(id){return Object.freeze([...(VASSALS_BY_TERRITORY.get(id)||[])]);}
export const FIXED_RELATION_STATS=Object.freeze({supreme:FIXED_SUPREME_RELATIONS.length,geographic:FIXED_GEOGRAPHIC_RELATIONS.length,total:FIXED_FACTION_RELATIONS.length,vassals:FIXED_FACTION_VASSALS.length,defaultType:DEFAULT_UNDECLARED_RELATION_TYPE});
